import pathlib,json,pandas as pd,numpy as np
q=pathlib.Path(__file__).resolve().parents[1];o=q/'outputs';r=pd.read_csv(o/'rna-all-features.tsv',sep='\t');cols=['LentiAS-1','LentiAS-2','LentiGFP-1','LentiGFP-2'];x=r[cols]
# Broad substring 'globin' also matched secretoglobins and plakoglobin. This refined selector captures erythroid hemoglobin descriptions only.
sel=r.description.fillna('').str.match(r'^(hemoglobin|beta globin|beta-globin)',case=False);p=r.loc[sel].copy();gfp=p[['norm_LentiGFP-1','norm_LentiGFP-2']].mean(axis=1);p['AS1_over_GFPmean']=p['norm_LentiAS-1']/gfp;p['AS2_over_GFPmean']=p['norm_LentiAS-2']/gfp;p.replace([np.inf,-np.inf],np.nan).to_csv(o/'rna-hemoglobin-specific.tsv',sep='\t',index=False)
pos=(x>0).all(axis=1)&~sel;sf=x.loc[pos].div(np.exp(np.log(x.loc[pos]).mean(axis=1)),axis=0).median();n=x.div(sf,axis=1);elig=(n.mean(axis=1)>=20)&~sel;y=np.log2(n.loc[elig]+1).T.to_numpy();y-=y.mean(axis=0);u,s,v=np.linalg.svd(y,full_matrices=False);pv=s*s/(s*s).sum()
a={'selector':'description begins hemoglobin or beta globin or beta-globin; excludes secretoglobins/plakoglobin and globin-associated proteins','symbols':p['#Geneid'].tolist(),'raw_sums':x.loc[sel].sum().to_dict(),'fractions':x.loc[sel].sum().div(x.sum()).to_dict(),'PCA_variance_excluding_hemoglobin':pv.tolist(),'PCA_coordinates_excluding_hemoglobin':dict(zip(cols,(u*s)[:,:2].tolist())),'ratios_excluding_hemoglobin':{g:float(n.loc[r['#Geneid']==g,cols[:2]].mean(axis=1).iloc[0]/n.loc[r['#Geneid']==g,cols[2:]].mean(axis=1).iloc[0]) for g in ['Pmp22','Egr2','Jun']},'interpretation':'Extreme group means largely reflect AS2 globin counts; AS1 is not similarly dominated. No coherent Gata1/Klf1/Tal1/Slc4a1/Alas2 erythroid program in panel. This weakens a broad erythroid-cell expansion explanation but does not identify source. Count-table totals and genes cannot establish cell identities or read provenance.'}
(o/'rna-hemoglobin-summary.json').write_text(json.dumps(a,indent=2,allow_nan=False));print(json.dumps(a,indent=2));print(p[['#Geneid',*cols,'AS1_over_GFPmean','AS2_over_GFPmean']].to_string(index=False))
